null,"co_investors":[],"deal_source_url":null},{"name":"Western Wireless Corporation","slug":"western-wireless","domain":null,"description":"Rural cellular-service provider created in August 1994 by Stanton and Hellman & Friedman by merging Pacific Northwest Cellular and General Cellular Corporation.","sector":"Telecommunications","hq":null,"status":null,"invested_year":1994,"exit_year":null,"fund_name":null,"source_url":"https://en.wikipedia.org/wiki/Western_Wireless_Corporation","deal_value":null,"deal_currency":null,"deal_value_basis":null,"stake_pct":null,"co_investors":[],"deal_source_url":null},{"name":"General Cellular Corporation","slug":"general-cellular","domain":null,"description":"Cellular operator in which Stanton Communications and Hellman & Friedman acquired a controlling interest in 1992; merged into Western Wireless in 1994.","sector":"Telecommunications","hq":null,"status":null,"invested_year":1992,"exit_year":null,"fund_name":null,"source_url":"https://en.wikipedia.org/wiki/Western_Wireless_Corporation","deal_value":null,"deal_currency":null,"deal_value_basis":null,"stake_pct":null,"co_investors":[],"deal_source_url":null},{"name":"VoiceStream Wireless","slug":"voicestream-wireless","domain":null,"description":"Wireless carrier whose common stock H&F partnerships reported holding for investment purposes in a 1999 Schedule 13D, with H&F officers serving as directors.","sector":"Telecommunications","hq":null,"status":null,"invested_year":null,"exit_year":null,"fund_name":null,"source_url":"https://www.sec.gov/Archives/edgar/data/1027300/0001047469-99-020131.txt","deal_value":null,"deal_currency":null,"deal_value_basis":null,"stake_pct":null,"co_investors":[],"deal_source_url":null},{"name":"American President Companies","slug":"american-president-companies","domain":null,"description":"Shipping and transportation company in which H&F partnerships held stock (converted from Series C preferred in 1995), with Warren Hellman and Tully Friedman serving as directors.","sector":"Transportation","hq":null,"status":null,"invested_year":null,"exit_year":null,"fund_name":null,"source_url":"https://www.sec.gov/Archives/edgar/data/949037/0000912057-95-006033.txt","deal_value":null,"deal_currency":null,"deal_value_basis":null,"stake_pct":null,"co_investors":[],"deal_source_url":null},{"name":"Great American Management & Investment","slug":"great-american-management-and-investment","domain":null,"description":"Company in which H&F partnerships held common stock and board nomination rights until selling all their shares under an exchange agreement in 1995.","sector":null,"hq":null,"status":"realized","invested_year":null,"exit_year":1995,"fund_name":null,"source_url":"https://www.sec.gov/Archives/edgar/data/949037/0000912057-95-007133.txt","deal_value":null,"deal_currency":null,"deal_value_basis":null,"stake_pct":null,"co_investors":[],"deal_source_url":null},{"name":"MobileMedia Corporation","slug":"mobilemedia","domain":null,"description":"Paging company in which Hellman & Friedman Capital Partners and affiliates reported beneficial ownership of about 23% of the Class A common stock as of January 1997.","sector":"Telecommunications","hq":null,"status":null,"invested_year":null,"exit_year":null,"fund_name":null,"source_url":"https://www.sec.gov/Archives/edgar/data/1027300/0000912057-97-005597.txt","deal_value":null,"deal_currency":null,"deal_value_basis":null,"stake_pct":null,"co_investors":[],"deal_source_url":null},{"name":"Mid Ocean Limited","slug":"mid-ocean","domain":null,"description":"Bermuda-based company whose Class A ordinary shares were held by Hellman & Friedman partnerships, reported in a Schedule 13G amendment filed in February 1997.","sector":"Financial Services","hq":"Hamilton, Bermuda","status":null,"invested_year":null,"exit_year":null,"fund_name":null,"source_url":"https://www.sec.gov/Archives/edgar/data/1027300/0000912057-97-005592.txt","deal_value":null,"deal_currency":null,"deal_value_basis":null,"stake_pct":null,"co_investors":[],"deal_source_url":null},{"name":"National Information Consortium (NIC)","slug":"national-information-consortium-nic","domain":null,"description":"E-government services company in which Hellman & Friedman Capital Partners III and affiliates reported about 6.0% beneficial ownership in a 2001 Schedule 13G.","sector":"Technology","hq":null,"status":null,"invested_year":null,"exit_year":null,"fund_name":null,"source_url":"https://www.sec.gov/Archives/edgar/data/1062988/0000903423-01-000062.txt","deal_value":null,"deal_currency":null,"deal_value_basis":null,"stake_pct":null,"co_investors":[],"deal_source_url":null},{"name":"Hoyts","slug":"hoyts","domain":null,"description":"Australian cinema chain sold to Hellman & Friedman and Lendlease after the 1993 death of Leon Fink; listed publicly in 1995.","sector":"Media & Entertainment","hq":null,"status":null,"invested_year":null,"exit_year":null,"fund_name":null,"source_url":"https://en.wikipedia.org/wiki/Hoyts","deal_value":null,"deal_currency":null,"deal_value_basis":null,"stake_pct":null,"co_investors":[],"deal_source_url":null},{"name":"Computer Software Group plc","slug":"computer-software-group","domain":null,"description":"UK software group taken private with HgCapital in April 2007, merged with IRIS and sold to Hellman & Friedman for £500m in July 2007.","sector":"Technology","hq":null,"status":null,"invested_year":2007,"exit_year":null,"fund_name":null,"source_url":"https://en.wikipedia.org/wiki/Vin_Murria","deal_value":null,"deal_currency":null,"deal_value_basis":null,"stake_pct":null,"co_investors":[],"deal_source_url":null}],"deals":[]}$pf$::jsonb;
  n_companies int;
  n_deals int;
begin
  select id into gp from public.companies
   where category = 'GP' and name = 'Hellman & Friedman'
   order by (source = 'master_directory') desc nulls last, created_at
   limit 1;
  if gp is null then raise exception 'sponsor % is not in the directory', 'Hellman & Friedman'; end if;

  insert into public.portfolio_companies as pc (external_key, gp_company_id, name, domain, description, sector, hq, status, invested_year, exit_year, fund_name,
      source, source_url, deal_value, deal_currency, deal_value_basis, stake_pct, co_investors, deal_source_url, researched_at)
  select gp::text || ':' || (c->>'slug'), gp, c->>'name', c->>'domain', c->>'description', c->>'sector', c->>'hq', c->>'status',
         (c->>'invested_year')::int, (c->>'exit_year')::int, c->>'fund_name', 'web_research', c->>'source_url',
         (c->>'deal_value')::numeric, c->>'deal_currency', c->>'deal_value_basis', (c->>'stake_pct')::numeric,
         coalesce(array(select jsonb_array_elements_text(c->'co_investors')), '{}'), c->>'deal_source_url', now()
    from jsonb_array_elements(doc->'companies') c
  on conflict (external_key) do update set
    name = case when pc.source = 'manual' then pc.name else excluded.name end,
    domain = coalesce(pc.domain, excluded.domain),
    description = case when pc.source = 'manual' then coalesce(pc.description, excluded.description) else coalesce(excluded.description, pc.description) end,
    sector = case when pc.source = 'manual' then coalesce(pc.sector, excluded.sector) else coalesce(excluded.sector, pc.sector) end,
    hq = case when pc.source = 'manual' then coalesce(pc.hq, excluded.hq) else coalesce(excluded.hq, pc.hq) end,
    status = coalesce(excluded.status, pc.status),
    invested_year = coalesce(excluded.invested_year, pc.invested_year),
    exit_year = coalesce(excluded.exit_year, pc.exit_year),
    fund_name = coalesce(excluded.fund_name, pc.fund_name),
    source_url = case when pc.source = 'manual' then coalesce(pc.source_url, excluded.source_url) else excluded.source_url end,
    deal_value = coalesce(excluded.deal_value, pc.deal_value),
    deal_currency = case when excluded.deal_value is not null then excluded.deal_currency else pc.deal_currency end,
    deal_value_basis = case when excluded.deal_value is not null then excluded.deal_value_basis else pc.deal_value_basis end,
    stake_pct = coalesce(excluded.stake_pct, pc.stake_pct),
    co_investors = case when cardinality(excluded.co_investors) > 0 then excluded.co_investors else pc.co_investors end,
    deal_source_url = coalesce(excluded.deal_source_url, pc.deal_source_url),
    researched_at = now();
  get diagnostics n_companies = row_count;

  insert into public.deals as d (external_key, date, date_text, kind, asset_class, target, target_kind, target_key, target_website, investor, investor_company_id,
      co_investors, seller, round, stake_pct, amount, currency, amount_basis, valuation, valuation_currency, headline, summary, source_name, source_url,
      evidence, verified, source)
  select x->>'key', (x->>'date')::date, x->>'date_text', x->>'kind', x->>'asset_class', x->>'target', 'company',
         public.borrower_key(coalesce(x->>'portco_name', x->>'target')), x->>'target_website', x->>'investor',
         case when (x->>'sponsor_is_investor')::boolean then gp else (select m.company_id from ingest.match_firm(x->>'investor', array['GP']) m) end,
         coalesce(array(select jsonb_array_elements_text(x->'co_investors')), '{}'), x->>'seller', x->>'round', (x->>'stake_pct')::numeric,
         (x->>'amount')::numeric, x->>'currency', x->>'amount_basis', (x->>'valuation')::numeric, x->>'valuation_currency',
         x->>'headline', x->>'summary', x->>'source_name', x->>'source_url', x->>'evidence', (x->>'verified')::boolean, 'web_research'
    from jsonb_array_elements(doc->'deals') x
  on conflict (external_key) do update set
    date = excluded.date, date_text = excluded.date_text, kind = excluded.kind, target = excluded.target, target_key = excluded.target_key,
    target_website = coalesce(excluded.target_website, d.target_website), investor = excluded.investor,
    investor_company_id = coalesce(excluded.investor_company_id, d.investor_company_id),
    co_investors = (select coalesce(array_agg(distinct v), '{}') from unnest(d.co_investors || excluded.co_investors) v),
    seller = coalesce(excluded.seller, d.seller), round = coalesce(excluded.round, d.round), stake_pct = coalesce(excluded.stake_pct, d.stake_pct),
    amount = excluded.amount, currency = excluded.currency, amount_basis = excluded.amount_basis,
    valuation = excluded.valuation, valuation_currency = excluded.valuation_currency, headline = excluded.headline,
    summary = coalesce(excluded.summary, d.summary), source_name = excluded.source_name, source_url = excluded.source_url,
    evidence = excluded.evidence, verified = coalesce(excluded.verified, d.verified);
  get diagnostics n_deals = row_count;

  update public.companies set portfolio_note = 'hf.com portfolio list (https://hf.com/our-portfolio/ popups = WP REST /wp-json/wp/v2/portfolio, 83 entries with sector/status/geography) + predecessor companies named on hf.com portfolio pages and news posts (/wp-json/wp/v2/posts) + Hyve (hf.com news), Cortex (PR Newswire), SEC EDGAR 13D/13G filings by H&F entities, Wikipedia', portfolio_researched_at = now() where id = gp;
  insert into ingest.log (what, detail) values ('load_portfolio', jsonb_build_object('sponsor', 'Hellman & Friedman', 'companies', n_companies, 'deals', n_deals));
end $pfdo$;
